head.script:
scwin.onpageload = function() {
    scwin.createWindow();
};
scwin.onpageunload = function() {};
scwin.createWindow = function() {
    var c_cnt = 1;
    var c_subName = "sub";
    for (var i = 0; i < c_cnt; i++) {
        var winObj = {
            title: c_subName + i,
            src: "windowContainer_popup_frameModal_WESD-652_(WSQ-4712)_popup.xml"
        }
        windowContainer1.createWindow(winObj);
    }
};
scwin.trigger1_onclick = function() {
    //scwin.createWindow();
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow0_wframe_btn_openWFramePopup1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('windowContainer1_subWindow0_wframe_popup0_header')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#windowContainer1_subWindow0').width() > 300 ", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
